```javascript
'use strict';
const fs = require('fs');

function main() {
  const n = parseInt(process.argv[2], 10) | 0;
  const rowBytes = (n + 7) >> 3;
  const header = 'P4\n' + n + ' ' + n + '\n';
  const headerLen = header.length;
  const total = headerLen + rowBytes * n;
  const out = Buffer.allocUnsafe(total);
  for (let i = 0; i < headerLen; i++) out[i] = header.charCodeAt(i);
  if (n <= 0) {
    writeAll(out, total);
    return;
  }
  const dataStart = headerLen;

  // Precompute per-column values
  const CrA = new Float64Array(n);
  const Cr2A = new Float64Array(n);
  for (let x = 0; x < n; x++) {
    const cr = 2 * x / n - 1.5;
    CrA[x] = cr;
    Cr2A[x] = cr * cr;
  }

  const half = n >> 1;
  for (let y = 0; y <= half; y++) {
    const ci = 2 * y / n - 1;
    const ci2 = ci * ci;
    const ci2q = ci2 * 0.25;
    let pos = dataStart + y * rowBytes;
    let byteAcc = 0;
    let bitCnt = 0;
    for (let x = 0; x < n; x++) {
      const cr = CrA[x];
      let bit;
      // main cardioid check
      const xe = cr - 0.25;
      const q = xe * xe + ci2;
      if (q * (q + xe) <= ci2q) {
        bit = 1;
      } else {
        const xb = cr + 1;
        if (xb * xb + ci2 <= 0.0625) {
          bit = 1;
        } else {
          let zr = cr, zi = ci, tr = Cr2A[x], ti = ci2;
          let rem = 49;
          do {
            zi = 2 * zr * zi + ci;
            zr = tr - ti + cr;
            tr = zr * zr;
            ti = zi * zi;
          } while (tr + ti <= 4 && --rem > 0);
          bit = tr + ti <= 4 ? 1 : 0;
        }
      }
      byteAcc = (byteAcc << 1) | bit;
      if (++bitCnt === 8) {
        out[pos++] = byteAcc;
        byteAcc = 0;
        bitCnt = 0;
      }
    }
    if (bitCnt !== 0) out[pos] = (byteAcc << (8 - bitCnt)) & 0xFF;
  }

  // mirror rows
  for (let y = 1; y <= half; y++) {
    const t = n - y;
    if (t !== y) {
      const s = dataStart + y * rowBytes;
      out.copy(out, dataStart + t * rowBytes, s, s + rowBytes);
    }
  }

  writeAll(out, total);
}

function writeAll(buf, len) {
  let off = 0;
  while (off < len) {
    off += fs.writeSync(1, buf, off, len - off);
  }
}

main();
```

