'use strict';
const fs = require('fs');

function main() {
  const n = parseInt(process.argv[2], 10) | 0;
  if (n <= 0) {
    // Degenerate: emit a valid empty header and exit.
    fs.writeSync(1, Buffer.from('P4\n0 0\n', 'latin1'));
    return;
  }
  const rowBytes = (n + 7) >> 3;
  const header = 'P4\n' + n + ' ' + n + '\n';
  const headerLen = header.length;
  const total = headerLen + rowBytes * n;
  const out = Buffer.allocUnsafe(total);
  for (let i = 0; i < headerLen; i++) out[i] = header.charCodeAt(i);
  const dataStart = headerLen;

  // Per-column precomputation (bit-identical to the reference formulas).
  const crA = new Float64Array(n);
  const cr2A = new Float64Array(n);
  for (let x = 0; x < n; x++) {
    const cr = 2 * x / n - 1.5;
    crA[x] = cr;
    cr2A[x] = cr * cr;
  }

  // Column ranges by which interior shortcut can apply:
  //   x <  xA : cr < -0.75  -> period-2 bulb test only
  //   x <  xB : cr <= 0.25  -> main cardioid test only
  //   x >= xB : cr >  0.25  -> no shortcut possible
  const xA = Math.ceil(3 * n / 8);
  const xB = Math.ceil(7 * n / 8);

  for (let y = 0; y < n; y++) {
    const ci = 2 * y / n - 1;
    const ci2 = ci * ci;
    const ci2q = ci2 * 0.25;
    let pos = dataStart + y * rowBytes;
    let byteAcc = 0;
    let bitCnt = 0;

    // --- range 1: bulb ---
    for (let x = 0; x < xA; x++) {
      const cr = crA[x];
      let bit;
      if ((cr + 1) * (cr + 1) + ci2 <= 0.0625) {
        bit = 1;
      } else {
        let zr = cr, zi = ci, tr = cr2A[x], ti = ci2;
        let count = 1;
        while (count < 50 && tr + ti <= 4) {
          zi = 2 * zr * zi + ci;
          zr = tr - ti + cr;
          tr = zr * zr;
          ti = zi * zi;
          count++;
        }
        bit = tr + ti <= 4 ? 1 : 0;
      }
      byteAcc = (byteAcc << 1) | bit;
      if (++bitCnt === 8) { out[pos++] = byteAcc; byteAcc = 0; bitCnt = 0; }
    }

    // --- range 2: cardioid ---
    for (let x = xA; x < xB; x++) {
      const cr = crA[x];
      let bit;
      const xe = cr - 0.25;
      const q = xe * xe + ci2;
      if (q * (q + xe) <= ci2q) {
        bit = 1;
      } else {
        let zr = cr, zi = ci, tr = cr2A[x], ti = ci2;
        let count = 1;
        while (count < 50 && tr + ti <= 4) {
          zi = 2 * zr * zi + ci;
          zr = tr - ti + cr;
          tr = zr * zr;
          ti = zi * zi;
          count++;
        }
        bit = tr + ti <= 4 ? 1 : 0;
      }
      byteAcc = (byteAcc << 1) | bit;
      if (++bitCnt === 8) { out[pos++] = byteAcc; byteAcc = 0; bitCnt = 0; }
    }

    // --- range 3: plain ---
    for (let x = xB; x < n; x++) {
      const cr = crA[x];
      let zr = cr, zi = ci, tr = cr2A[x], ti = ci2;
      let count = 1;
      while (count < 50 && tr + ti <= 4) {
        zi = 2 * zr * zi + ci;
        zr = tr - ti + cr;
        tr = zr * zr;
        ti = zi * zi;
        count++;
      }
      const bit = tr + ti <= 4 ? 1 : 0;
      byteAcc = (byteAcc << 1) | bit;
      if (++bitCnt === 8) { out[pos++] = byteAcc; byteAcc = 0; bitCnt = 0; }
    }

    if (bitCnt !== 0) out[pos] = (byteAcc << (8 - bitCnt)) & 0xFF;
  }

  // Synchronous, complete write of the whole image.
  let off = 0;
  while (off < total) {
    off += fs.writeSync(1, out, off, total - off);
  }
}

main();
