```javascript
'use strict';

const fs = require('fs');

function main() {
  let n = parseInt(process.argv[2], 10);
  if (!(n > 0)) n = 0;

  const header = 'P4\n' + n + ' ' + n + '\n';
  const headerLen = header.length;

  if (n === 0) {
    fs.writeSync(1, header, 'latin1');
    return;
  }

  const rowBytes = (n + 7) >> 3;
  const total = headerLen + rowBytes * n;
  const out = Buffer.allocUnsafe(total);
  for (let i = 0; i < headerLen; i++) out[i] = header.charCodeAt(i);
  const dataStart = headerLen;

  // Per-column constants (identical expressions to the reference implementation,
  // so all floating point results match bit-for-bit).
  const crA = new Float64Array(n);   // cr = 2x/n - 1.5
  const cr2A = new Float64Array(n);  // cr*cr  (== |z1|^2 real part squared)
  const cbA = new Float64Array(n);   // (cr+1)^2  for the period-2 bulb test
  const xeA = new Float64Array(n);   // cr - 0.25 for the main cardioid test
  const xe2A = new Float64Array(n);  // (cr-0.25)^2
  for (let x = 0; x < n; x++) {
    const cr = 2 * x / n - 1.5;
    crA[x] = cr;
    cr2A[x] = cr * cr;
    cbA[x] = (cr + 1) * (cr + 1);
    const xe = cr - 0.25;
    xeA[x] = xe;
    xe2A[x] = xe * xe;
  }

  // Shortcut applicability ranges (proved exactly):
  //   x <  xA : cr < -0.75  -> only the period-2 bulb test can hit
  //   x <  xB : cr <= 0.375 -> only the main cardioid test can hit
  //   x >= xB : cr >  0.375 -> neither can hit, iterate directly
  const xA = Math.ceil(3 * n / 8);
  const xB = Math.floor(15 * n / 16) + 1;

  for (let y = 0; y < n; y++) {
    const ci = 2 * y / n - 1;
    const ci2 = ci * ci;
    const ci2q = ci2 * 0.25;
    let pos = dataStart + y * rowBytes;
    let byteAcc = 0;
    let bitCnt = 0;

    for (let x = 0; x < xB; x++) {
      let bit;
      if (x < xA) {
        // period-2 bulb: |c+1|^2 <= 1/16  =>  inside the set
        if (cbA[x] + ci2 <= 0.0625) {
          byteAcc = (byteAcc << 1) | 1;
          if (++bitCnt === 8) { out[pos++] = byteAcc; byteAcc = 0; bitCnt = 0; }
          continue;
        }
      } else {
        // main cardioid: q*(q + (cr-1/4)) <= (ci/2)^2  =>  inside the set
        const q = xe2A[x] + ci2;
        if (q * (q + xeA[x]) <= ci2q) {
          byteAcc = (byteAcc << 1) | 1;
          if (++bitCnt === 8) { out[pos++] = byteAcc; byteAcc = 0; bitCnt = 0; }
          continue;
        }
      }
      // plain iteration (bit-identical to the reference)
      let zr = crA[x], zi = ci, tr = cr2A[x], ti = ci2;
      let rem = 49;
      while (tr + ti <= 4 && rem-- > 0) {
        zi = 2 * zr * zi + ci;
        zr = tr - ti + cr;
        tr = zr * zr;
        ti = zi * zi;
      }
      byteAcc = (byteAcc << 1) | (tr + ti <= 4 ? 1 : 0);
      if (++bitCnt === 8) { out[pos++] = byteAcc; byteAcc = 0; bitCnt = 0; }
    }

    for (let x = xB; x < n; x++) {
      let zr = crA[x], zi = ci, tr = cr2A[x], ti = ci2;
      let rem = 49;
      while (tr + ti <= 4 && rem-- > 0) {
        zi = 2 * zr * zi + ci;
        zr = tr - ti + cr;
        tr = zr * zr;
        ti = zi * zi;
      }
      byteAcc = (byteAcc << 1) | (tr + ti <= 4 ? 1 : 0);
      if (++bitCnt === 8) { out[pos++] = byteAcc; byteAcc = 0; bitCnt = 0; }
    }

    if (bitCnt !== 0) out[pos] = (byteAcc << (8 - bitCnt)) & 0xFF;
  }

  let off = 0;
  while (off < total) {
    off += fs.writeSync(1, out, off, total - off);
  }
}

main();
```

