```c
void offset_momentum(int nbodies, struct body * bodies)
{
  double px = 0.0, py = 0.0, pz = 0.0;
  for (int i = 0; i < nbodies; ++i) {
    px += bodies[i].vx * bodies[i].mass;
    py += bodies[i].vy * bodies[i].mass;
    pz += bodies[i].vz * bodies[i].mass;
  }
  bodies[0].vx = -px / SOLAR_MASS;
  bodies[0].vy = -py / SOLAR_MASS;
  bodies[0].vz = -pz / SOLAR_MASS;
}
```

Energy computation:

```c
double energy(int nbodies, struct body * bodies)
{
  double e = 0.0;
  for (int i=0; i < nbodies; ++i) {
    struct body const & bi = bodies[i];
    e += bi.mass * (bi.vx*bi.vx + bi.vy*bi.vy + bi.vz*bi.vz) / 2.0;
    for (int j=i+1; j < nbodies; ++j) {
      struct body const & bj = bodies[j];
      double dx = bi.x - bj.x;
      double dy = bi.y - bj.y;
      double dz = bi.z - bj.z;
      double distance2 = dx*dx + dy*dy + dz*dz;
      e -= (bi.mass * bj.mass) / sqrt(distance2);
    }
  }
  return e;
}
```

Advance (symplectic method):

```c
void advance(int nbodies, struct body * bodies, double dt)
{
  for (int i=0; i < nbodies; ++i) {
    struct body & bi = bodies[i];
    for (int j=i+1; j < nbodies; ++j) {
      struct body & bj = bodies[j];
      double dx = bi.x - bj.x;
      double dy = bi.y - bj.y;
      double dz = bi.z - bj.z;
      double distance2 = dx*dx + dy*dy + dz*dz;
      double mag = dt / (distance2 * sqrt(distance2));
      bi.vx -= dx * bj.mass * mag;
      bi.vy -= dy * bj.mass * mag;
      bi.vz -= dz * bj.mass * mag;
      bj.vx += dx * bi.mass * mag;
      bj.vy += dy * bi.mass * mag;
      bj.vz += dz * bi.mass * mag;
    }
  }
  for (int i=0; i < nbodies; ++i) {
    struct body & bi = bodies[i];
    bi.x += dt * bi.vx;
    bi.y += dt * bi.vy;
    bi.z += dt * bi.vz;
  }
}
```

