// whose cumulative probability is strictly greater than r.  r depends only
// on s, so precompute the selected symbol for every possible seed value.
// This is bit-identical to evaluating each draw individually.
function buildLookup(table) {
  const n = table.length;
  const cum = new Float64Array(n);
  const sym = new Uint8Array(n);
  let acc = 0;
  for (let i = 0; i < n; i++) {
    acc += table[i][0];
    cum[i] = acc;
    sym[i] = table[i][1];
