```javascript
'use strict';

const fs = require('fs');

const IM = 139968;
const IA = 3877;
const IC = 29573;

const ALU =
  'GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA' +
  'TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT' +
  'AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG' +
  'GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG' +
  'CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA';

const ALU_BUF = Buffer.from(ALU, 'latin1');

const IUB_TABLE = [
  [0.27, 97],  // a
  [0.12, 99],  // c
  [0.12, 103], // g
  [0.27, 116], // t
  [0.02, 66],  // B
  [0.02, 68],  // D
  [0.02, 72],  // H
  [0.02, 75],  // K
  [0.02, 77],  // M
  [0.02, 78],  // N
  [0.02, 82],  // R
  [0.02, 83],  // S
  [0.02, 86],  // V
  [0.02, 87],  // W
  [0.02, 89],  // Y
];

const HUMAN_TABLE = [
  [0.3029549426680, 97],  // a
  [0.1979883004921, 99],  // c
  [0.1975473066391, 103], // g
  [0.3015094502008, 116], // t
];

function buildLut(table) {
  const n = table.length;
  const cum = new Float64Array(n);
  const chars = new Uint8Array(n);
  let s = 0.0;
  for (let i = 0; i < n; i++) {
    s += table[i][0];
    cum[i] = s;
    chars[i] = table[i][1];
  }
  const lut = new Uint8Array(IM);
  let j = 0;
  for (let i = 0; i < IM; i++) {
    const r = i / IM;
    while (j < n - 1 && cum[j] <= r) j++;
    lut[i] = chars[j];
  }
  return lut;
}

const LUT_IUB = buildLut(IUB_TABLE);
const LUT_HUMAN = buildLut(HUMAN_TABLE);

let seed = 42;

function writeAll(buf) {
  const len = buf.length;
  let off = 0;
  while (off < len) {
    off += fs.writeSync(1, buf, off, len - off);
  }
}

function emitAlu(len) {
  const header = Buffer.from('>ONE Homo sapiens alu\n', 'latin1');
  if (len <= 0) {
    writeAll(header);
    return;
  }
  const lines = Math.ceil(len / 60);
  const buf = Buffer.allocUnsafe(header.length + len + lines);
  header.copy(buf, 0);
  const src = ALU_BUF;
  const slen = src.length;
  let pos = header.length;
  let col = 0;
  let idx = 0;
  for (let i = 0; i < len; i++) {
    buf[pos++] = src[idx];
    if (++idx === slen) idx = 0;
    if (++col === 60) {
      buf[pos++] = 10;
      col = 0;
    }
  }
  if (col !== 0) buf[pos] = 10;
  writeAll(buf);
}

function emitRandom(lut, len, headerText) {
  const header = Buffer.from(headerText, 'latin1');
  if (len <= 0) {
    writeAll(header);
    return;
  }
  const lines = Math.ceil(len / 60);
  const buf = Buffer.allocUnsafe(header.length + len + lines);
  header.copy(buf, 0);
  let pos = header.length;
  let col = 0;
  let s = seed;
  for (let i = 0; i < len; i++) {
    s = (s * IA + IC) % IM;
    buf[pos++] = lut[s];
    if (++col === 60) {
      buf[pos++] = 10;
      col = 0;
    }
  }
  if (col !== 0) buf[pos] = 10;
  seed = s;
  writeAll(buf);
}

function main() {
  const N = parseInt(process.argv[2], 10);
  const n = Number.isFinite(N) && N > 0 ? N : 0;
  emitAlu(2 * n);
  emitRandom(LUT_IUB, 3 * n, '>TWO IUB ambiguity codes\n');
  emitRandom(LUT_HUMAN, 5 * n, '>THREE Homo sapiens frequency\n');
}

main();
```

