```javascript
'use strict';

/*
 * fasta benchmark - generate three DNA sequences in FASTA format.
 *
 * Usage: node fasta.js N
 */

const fs = require('fs');

// Linear congruential generator (shared by both random sections).
const IM = 139968;
const IA = 3877;
const IC = 29573;

let seed = 42;

// ALU repeat sequence (287 characters).
const ALU =
  'GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA' +
  'TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT' +
  'AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG' +
  'GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG' +
  'CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA';

const ALU_CODES = Buffer.from(ALU, 'latin1');

// Weighted symbol tables in the required order: [probability, charCode].
const IUB_TABLE = [
  [0.27, 97],  [0.12, 99],  [0.12, 103], [0.27, 116], // a c g t
  [0.02, 66],  [0.02, 68],  [0.02, 72],  [0.02, 75],  // B D H K
  [0.02, 77],  [0.02, 78],  [0.02, 82],  [0.02, 83],  // M N R S
  [0.02, 86],  [0.02, 87],  [0.02, 89],               // V W Y
];

const HUMAN_TABLE = [
  [0.3029549426680, 97],   // a
  [0.1979883004921, 99],   // c
  [0.1975473066391, 103],  // g
  [0.3015094502008, 116],  // t
];

// For every possible seed value s in [0, IM) the draw value is r = s / IM
// and the chosen symbol is the first whose cumulative probability is
// strictly greater than r. Precomputing this table makes each draw O(1)
// while reproducing the per-draw floating point behaviour exactly.
function buildLookup(table) {
  const n = table.length;
  const cum = new Float64Array(n);
  const sym = new Uint8Array(n);
  let acc = 0;
  for (let i = 0; i < n; i++) {
    acc += table[i][0];
    cum[i] = acc;
    sym[i] = table[i][1];
  }
  const lut = new Uint8Array(IM);
  let j = 0;
  for (let s = 0; s < IM; s++) {
    const r = s / IM;
    while (j < n - 1 && cum[j] <= r) j++;
    lut[s] = sym[j];
  }
  return lut;
}

const IUB_LUT = buildLookup(IUB_TABLE);
const HUMAN_LUT = buildLookup(HUMAN_TABLE);

// Write a whole buffer to fd 1, retrying on partial writes.
function writeAll(buf) {
  const len = buf.length;
  let off = 0;
  while (off < len) {
    try {
      off += fs.writeSync(1, buf, off, len - off);
    } catch (e) {
      if (e && e.code === 'EAGAIN') continue;
      throw e;
    }
  }
}

// Segment size for output buffering: a multiple of the 60-column line width.
const SEG_CHARS = 60 * 16384;

// Emit `len` characters of the cyclic ALU repeat, wrapped at 60 columns.
function emitAlu(len) {
  writeAll(Buffer.from('>ONE Homo sapiens alu\n', 'latin1'));
  if (len <= 0) return;
  const src = ALU_CODES;
  const slen = src.length;
  let idx = 0;
  let emitted = 0;
  while (emitted < len) {
    const chars = Math.min(SEG_CHARS, len - emitted);
    const lines = Math.ceil(chars / 60);
    const buf = Buffer.allocUnsafe(chars + lines);
    let b = 0;
    const fullLines = (chars / 60) | 0;
    for (let l = 0; l < fullLines; l++) {
      for (let c = 0; c < 60; c++) {
        buf[b++] = src[idx];
        if (++idx === slen) idx = 0;
      }
      buf[b++] = 10;
    }
    const rest = chars - fullLines * 60;
    for (let c = 0; c < rest; c++) {
      buf[b++] = src[idx];
      if (++idx === slen) idx = 0;
    }
    if (rest !== 0) buf[b++] = 10;
    writeAll(buf);
    emitted += chars;
  }
}

// Emit `len` characters drawn from the shared LCG via `lut`, wrapped at 60.
function emitRandom(lut, len, header) {
  writeAll(Buffer.from(header, 'latin1'));
  if (len <= 0) return;
  let s = seed;
  let emitted = 0;
  while (emitted < len) {
    const chars = Math.min(SEG_CHARS, len - emitted);
    const lines = Math.ceil(chars / 60);
    const buf = Buffer.allocUnsafe(chars + lines);
    let b = 0;
    const fullLines = (chars / 60) | 0;
    for (let l = 0; l < fullLines; l++) {
      for (let c = 0; c < 60; c++) {
        s = (s * IA + IC) % IM;
        buf[b++] = lut[s];
      }
      buf[b++] = 10;
    }
    const rest = chars - fullLines * 60;
    for (let c = 0; c < rest; c++) {
      s = (s * IA + IC) % IM;
      buf[b++] = lut[s];
    }
    if (rest !== 0) buf[b++] = 10;
    writeAll(buf);
    emitted += chars;
  }
  seed = s;
}

function main() {
  const n = parseInt(process.argv[2], 10);
  const N = n > 0 && Number.isFinite(n) ? n : 0;

  emitAlu(2 * N);
  emitRandom(IUB_LUT, 3 * N, '>TWO IUB ambiguity codes\n');
  emitRandom(HUMAN_LUT, 5 * N, '>THREE Homo sapiens frequency\n');
}

main();
