```javascript
'use strict';

// fasta benchmark (Computer Language Benchmarks Game) - Node.js
// Usage: node fasta.js N

const fs = require('fs');

// --- Shared linear congruential random generator -------------------------
const IM = 139968;
const IA = 3877;
const IC = 29573;

let seed = 42;

// --- ALU sequence (287 characters, no randomness) ------------------------
const ALU =
  'GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA' +
  'TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT' +
  'AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG' +
  'GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG' +
  'CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA';

const ALU_CODES = Buffer.from(ALU, 'latin1');

// --- Weighted symbol tables (in the required order) ----------------------
// Each entry: [probability, character code]
const IUB_TABLE = [
  [0.27, 97],  [0.12, 99],  [0.12, 103], [0.27, 116], // a c g t
  [0.02, 66],  [0.02, 68],  [0.02, 72],  [0.02, 75],  // B D H K
  [0.02, 77],  [0.02, 78],  [0.02, 82],  [0.02, 83],  // M N R S
  [0.02, 86],  [0.02, 87],  [0.02, 89],               // V W Y
];

const HUMAN_TABLE = [
  [0.3029549426680, 97],  // a
  [0.1979883004921, 99],  // c
  [0.1975473066391, 103], // g
  [0.3015094502008, 116], // t
];

// A draw with seed value s uses r = s / IM and selects the first symbol
// whose cumulative probability is strictly greater than r.  Since r depends
// only on s, precompute the choice for every possible seed value; this is
// bit-identical to evaluating each draw individually but much faster.
function buildLookup(table) {
  const n = table.length;
  const cum = new Float64Array(n);
  const sym = new Uint8Array(n);
  let acc = 0;
  for (let i = 0; i < n; i++) {
    acc += table[i][0];
    cum[i] = acc;
    sym[i] = table[i][1];
  }
  const lut = new Uint8Array(IM);
  let j = 0;
  for (let s = 0; s < IM; s++) {
    const r = s / IM;
    while (j < n - 1 && cum[j] <= r) j++;
    lut[s] = sym[j];
  }
  return lut;
}

const IUB_LUT = buildLookup(IUB_TABLE);
const HUMAN_LUT = buildLookup(HUMAN_TABLE);

// --- Output ---------------------------------------------------------------
function writeAll(buf) {
  const len = buf.length;
  let off = 0;
  while (off < len) {
    try {
      off += fs.writeSync(1, buf, off, len - off);
    } catch (e) {
      if (e && e.code === 'EAGAIN') continue;
      throw e;
    }
  }
}

const SEG_CHARS = 60 * 16384; // chars per buffered segment (multiple of 60)

// Section ONE: cyclic repetition of the ALU string, wrapped at 60 columns.
function emitAlu(len) {
  writeAll(Buffer.from('>ONE Homo sapiens alu\n', 'latin1'));
  if (len <= 0) return;
  const src = ALU_CODES;
  const slen = src.length;
  let idx = 0;
  let done = 0;
  while (done < len) {
    const chars = Math.min(SEG_CHARS, len - done);
    const lines = Math.ceil(chars / 60);
    const buf = Buffer.allocUnsafe(chars + lines);
    let b = 0;
    const fullLines = (chars / 60) | 0;
    for (let l = 0; l < fullLines; l++) {
      for (let c = 0; c < 60; c++) {
        buf[b++] = src[idx];
        if (++idx === slen) idx = 0;
      }
      buf[b++] = 10;
    }
    const rest = chars - fullLines * 60;
    for (let c = 0; c < rest; c++) {
      buf[b++] = src[idx];
      if (++idx === slen) idx = 0;
    }
    if (rest !== 0) buf[b++] = 10;
    writeAll(buf);
    done += chars;
  }
}

// Random sections: `len` draws from the shared LCG, mapped through `lut`.
function emitRandom(lut, len, header) {
  writeAll(Buffer.from(header, 'latin1'));
  if (len <= 0) return;
  let s = seed;
  let done = 0;
  while (done < len) {
    const chars = Math.min(SEG_CHARS, len - done);
    const lines = Math.ceil(chars / 60);
    const buf = Buffer.allocUnsafe(chars + lines);
    let b = 0;
    const fullLines = (chars / 60) | 0;
    for (let l = 0; l < fullLines; l++) {
      for (let c = 0; c < 60; c++) {
        s = (s * IA + IC) % IM;
        buf[b++] = lut[s];
      }
      buf[b++] = 10;
    }
    const rest = chars - fullLines * 60;
    for (let c = 0; c < rest; c++) {
      s = (s * IA + IC) % IM;
      buf[b++] = lut[s];
    }
    if (rest !== 0) buf[b++] = 10;
    writeAll(buf);
    done += chars;
  }
  seed = s;
}

function main() {
  const parsed = parseInt(process.argv[2], 10);
  const N = parsed > 0 ? parsed : 0;

  emitAlu(2 * N);
  emitRandom(IUB_LUT, 3 * N, '>TWO IUB ambiguity codes\n');
  emitRandom(HUMAN_LUT, 5 * N, '>THREE Homo sapiens frequency\n');
}

main();
```

