            if (i + 4 <= L && seq[i + 3] === 0) {
                frag[1]++;                                       // GGTA
                if (i + 6 <= L && seq[i + 4] === 3 && seq[i + 5] === 3) {
                    frag[2]++;                                   // GGTATT
                    if (i + 12 <= L &&
                        seq[i + 6] === 3 && seq[i + 7] === 3 &&
                        seq[i + 8] === 0 && seq[i + 9] === 0 &&
                        seq[i + 10] === 3 && seq[i + 11] === 3) {
                        frag[3]++;                               // GGTATTTTAATT
                        if (i + 18 <= L &&
                            seq[i + 12] === 3 && seq[i + 13] === 0 &&
                            seq[i + 14] === 3 && seq[i + 15] === 0 &&
                            seq[i + 16] === 2 && seq[i + 17] === 3) {
                            frag[4]++;                           // GGTATTTTAATTTATAGT
                        }
                    }
                }
            }
        }
    }

    // ------------------------------------------------------------------
    // Report.
    // ------------------------------------------------------------------
    const byCountThenName = (a, b) =>
        (b[1] - a[1]) || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0);

    const ones = [];
    for (let c = 0; c < nb; c++) {
        if (count1[c] > 0) ones.push([String.fromCharCode(codeToByte[c]), count1[c]]);
    }
    ones.sort(byCountThenName);

    const twos = [];
    for (let p = 0; p < nb; p++) {
        const chP = String.fromCharCode(codeToByte[p]);
        const row = p * nb;
        for (let c = 0; c < nb; c++) {
            const v = count2[row + c];
            if (v > 0) twos.push([chP + String.fromCharCode(codeToByte[c]), v]);
        }
    }
    twos.sort(byCountThenName);

    const out = [];
    for (let k = 0; k < ones.length; k++) {
        out.push(ones[k][0] + ' ' + (ones[k][1] * 100 / L).toFixed(3));
    }
    out.push('');
    const total2 = L > 1 ? L - 1 : 1;                      // number of 2-mers
    for (let k = 0; k < twos.length; k++) {
        out.push(twos[k][0] + ' ' + (twos[k][1] * 100 / total2).toFixed(3));
    }
    out.push('');

    const names = ['GGT', 'GGTA', 'GGTATT', 'GGTATTTTAATT', 'GGTATTTTAATTTATAGT'];
    for (let k = 0; k < names.length; k++) {
        out.push(frag[k] + '\t' + names[k]);
    }
    process.stdout.write(out.join('\n') + '\n');
}

main();
```

## Approach

This is the classic FASTA reverse-complement task. The key observations:

1. **Line wrapping is preserved automatically if newlines never move.** Within a sequence, the output must have lines of exactly the same lengths as the input. Since revcomp of the concatenated sequence re-wrapped at the same lengths puts every `\n` at the *same byte offset*, we can transform the buffer in place: keep all newline bytes fixed, and reverse+complement only the sequence bytes between them.

2. **Two-pointer in-place transform:** one cursor scans forward, one backward, both skipping newline bytes; each pair of non-newline bytes is swapped *and* complemented (each side needs the complement of the other's original value). A lone middle byte just gets complemented. Headers (lines starting with `>`) are located first and left untouched.

3. **Complement table:** a 256-entry `Uint8Array` identity table, overridden with A↔T, C↔G, U→A, R↔Y, K↔M, B↔V, D↔H; S, W, N (and anything unlisted) map to themselves. Lowercase input is mapped to its uppercase complement.

4. **I/O:** read all of stdin synchronously (`fs.readFileSync(0)`), transform in place, then write the buffer to fd 1 with a partial-write-safe loop. The `N` CLI argument is parsed per the harness contract but the transformation is entirely driven by stdin content.

```javascript
// reverse-complement — read FASTA from stdin, emit reverse-complemented FASTA
// to stdout, preserving headers and the original line wrapping.

const fs = require('fs');

// Harness contract: N arrives as the first CLI argument. The transformation
// is fully determined by the stdin content, so N is parsed and ignored.
if (process.argv.length > 2) parseInt(process.argv[2], 10);

// IUPAC complement table (byte -> byte). Everything not listed maps to itself.
const comp = new Uint8Array(256);
for (let i = 0; i < 256; i++) comp[i] = i;

function pair(a, b) {
  comp[a.charCodeAt(0)] = b.charCodeAt(0);
  comp[b.charCodeAt(0)] = a.charCodeAt(0);
}
pair('A', 'T'); // A<->T
pair('C', 'G'); // C<->G
pair('R', 'Y'); // R<->Y
pair('K', 'M'); // K<->M
pair('B', 'V'); // B<->V
pair('D', 'H'); // D<->H
comp['U'.charCodeAt(0)] = 'A'.charCodeAt(0); // U->A
// S, W, N map to themselves (already the identity default).
// Lowercase codes are complemented to their uppercase counterpart.
comp['a'.charCodeAt(0)] = 'T'.charCodeAt(0);
comp['t'.charCodeAt(0)] = 'A'.charCodeAt(0);
comp['c'.charCodeAt(0)] = 'G'.charCodeAt(0);
comp['g'.charCodeAt(0)] = 'C'.charCodeAt(0);
comp['u'.charCodeAt(0)] = 'A'.charCodeAt(0);
comp['r'.charCodeAt(0)] = 'Y'.charCodeAt(0);
comp['y'.charCodeAt(0)] = 'R'.charCodeAt(0);
comp['k'.charCodeAt(0)] = 'M'.charCodeAt(0);
comp['m'.charCodeAt(0)] = 'K'.charCodeAt(0);
comp['b'.charCodeAt(0)] = 'V'.charCodeAt(0);
comp['v'.charCodeAt(0)] = 'B'.charCodeAt(0);
comp['d'.charCodeAt(0)] = 'H'.charCodeAt(0);
comp['h'.charCodeAt(0)] = 'D'.charCodeAt(0);

const buf = fs.readFileSync(0);
const n = buf.length;

// Locate every FASTA header line: '>' at the start of a line.
const headers = [];
if (n > 0 && buf[0] === 62) headers.push(0);
for (let i = 1; i < n; i++) {
  if (buf[i] === 62 && buf[i - 1] === 10) headers.push(i);
}

// Reverse-complement one sequence region in place. Newline (and carriage
// return) bytes stay exactly where they are, which preserves the original
// line wrapping; the sequence bytes are reversed and complemented.
function revcompRegion(start, end) {
  let j = start;    // forward cursor
  let i = end - 1;  // backward cursor
  while (j < i) {
    const cj = buf[j];
    if (cj === 10 || cj === 13) { j++; continue; }
    const ci = buf[i];
    if (ci === 10 || ci === 13) { i--; continue; }
    buf[j] = comp[ci];
    buf[i] = comp[cj];
    j++;
    i--;
  }
  if (j === i) {
    const c = buf[j];
    if (c !== 10 && c !== 13) buf[j] = comp[c];
  }
}

for (let h = 0; h < headers.length; h++) {
  const hStart = headers[h];
  let e = hStart;
  while (e < n && buf[e] !== 10) e++; // end of header line ('\n' position or n)
  const seqStart = e < n ? e + 1 : n;
  const seqEnd = h + 1 < headers.length ? headers[h + 1] : n;
  if (seqStart < seqEnd) revcompRegion(seqStart, seqEnd);
}

// Write the transformed buffer to stdout, tolerating partial writes.
let off = 0;
while (off < n) {
  off += fs.writeSync(1, buf, off, n - off);
}
